defmodule CodeMySpec.Repo.SqliteMigrations.Baseline do
  use Ecto.Migration

  # The desktop's SQLite schema as of the Postgres migration this file is named
  # for, generated by `scripts/sqlite_baseline.py`. Every Postgres migration
  # after it has a counterpart here, under the same version.
  def up do
    :code_my_spec
    |> Application.app_dir("priv/sqlite/baseline.sql")
    |> File.read!()
    |> String.split(~r/;\s*\n\s*\n/, trim: true)
    |> Enum.map(&String.trim/1)
    |> Enum.reject(&(&1 == ""))
    |> Enum.each(&execute/1)
  end

  def down, do: raise(Ecto.MigrationError, "the baseline cannot be rolled back")
end
